def strategy(hist, state, pos, ind) -> dict:
    close = hist.close
    high = hist.high
    low = hist.low

    n = len(hist) - 1
    if n < 100:
        return {"target": pos, "stop": None, "take": None}

    sma5 = ind.sma(close, 5)
    sma100 = ind.sma(close, 100)

    c0 = sma5[-1]
    c1 = sma100[-1]
    p0 = sma5[-2]
    p1 = sma100[-2]

    long_cross = False
    short_cross = False
    if not (np.isnan(c0) or np.isnan(c1) or np.isnan(p0) or np.isnan(p1)):
        long_cross = (p0 <= p1) and (c0 > c1)
        short_cross = (p0 >= p1) and (c0 < c1)

    atr14 = ind.atr(hist, 14)
    atr = atr14[-1]
    if np.isnan(atr) or atr <= 0:
        atr = 0.0

    def getf(k, default):
        v = state.get(k, default)
        return float(v)

    def geti(k, default):
        v = state.get(k, default)
        return int(v)

    def getb(k, default):
        v = state.get(k, default)
        return bool(v)

    current_pos = float(pos)
    target = current_pos
    stop = None
    take = None

    entry_dir = int(state.get("entry_dir", 0))
    if current_pos == 0.0:
        if "entry_dir" in state:
            del state["entry_dir"]
        if "entry_price" in state:
            del state["entry_price"]
        if "entry_atr" in state:
            del state["entry_atr"]
        if "entry_bar" in state:
            del state["entry_bar"]
        if "box_anchor" in state:
            del state["box_anchor"]
        if "extreme" in state:
            del state["extreme"]
    else:
        if "entry_price" not in state:
            state["entry_price"] = float(close[-1])
        if "entry_atr" not in state:
            state["entry_atr"] = float(atr)
        if "entry_bar" not in state:
            state["entry_bar"] = int(n)
        if "box_anchor" not in state:
            state["box_anchor"] = float(state["entry_price"])
        if "extreme" not in state:
            state["extreme"] = float(state["entry_price"])

    if current_pos == 0.0:
        if long_cross:
            target = 0.75
            state["entry_dir"] = 1
            state["entry_price"] = float(close[-1])
            state["entry_atr"] = float(atr)
            state["entry_bar"] = int(n)
            state["box_anchor"] = float(close[-1])
            state["extreme"] = float(close[-1])
        elif short_cross:
            target = -0.75
            state["entry_dir"] = -1
            state["entry_price"] = float(close[-1])
            state["entry_atr"] = float(atr)
            state["entry_bar"] = int(n)
            state["box_anchor"] = float(close[-1])
            state["extreme"] = float(close[-1])
    else:
        ep = float(state.get("entry_price", close[-1]))
        ea = float(state.get("entry_atr", atr))
        eb = int(state.get("entry_bar", n))
        anchor = float(state.get("box_anchor", ep))
        extreme = float(state.get("extreme", ep))

        if current_pos > 0:
            if long_cross:
                target = current_pos
            elif short_cross:
                target = 0.0
            else:
                if high[-1] > extreme:
                    extreme = float(high[-1])
                state["extreme"] = extreme

                while close[-1] >= anchor + 2.0 * ea:
                    anchor += 2.0 * ea
                state["box_anchor"] = anchor

                stop = anchor - 2.0 * ea
                take = anchor + 2.0 * ea

                trail = extreme - 3.0 * ea
                if stop is None or trail > stop:
                    stop = trail

                if n - eb >= 32:
                    target = 0.0
                else:
                    target = current_pos
        else:
            if short_cross:
                target = current_pos
            elif long_cross:
                target = 0.0
            else:
                if low[-1] < extreme:
                    extreme = float(low[-1])
                state["extreme"] = extreme

                while close[-1] <= anchor - 2.0 * ea:
                    anchor -= 2.0 * ea
                state["box_anchor"] = anchor

                stop = anchor + 2.0 * ea
                take = anchor - 2.0 * ea

                trail = extreme + 3.0 * ea
                if stop is None or trail < stop:
                    stop = trail

                if n - eb >= 32:
                    target = 0.0
                else:
                    target = current_pos

    if target > 1.0:
        target = 1.0
    if target < -1.0:
        target = -1.0

    target = round(target / 0.05) * 0.05
    target = float(max(-1.0, min(1.0, target)))

    return {"target": target, "stop": stop, "take": take}

