def strategy(hist, state, pos, ind) -> dict:
    close = hist.close
    high = hist.high
    low = hist.low

    n = len(hist)
    if n < 201:
        return {"target": float(pos), "stop": None, "take": None}

    sma_fast = ind.sma(close, 5)
    sma_slow = ind.sma(close, 200)
    atr14 = ind.atr(hist, 14)

    i = n - 1
    prev = i - 1

    fast_now = sma_fast[i]
    slow_now = sma_slow[i]
    fast_prev = sma_fast[prev]
    slow_prev = sma_slow[prev]

    bull_signal = (
        not (math.isnan(fast_now) or math.isnan(slow_now) or math.isnan(fast_prev) or math.isnan(slow_prev))
        and fast_prev <= slow_prev
        and fast_now > slow_now
    )
    bear_signal = (
        not (math.isnan(fast_now) or math.isnan(slow_now) or math.isnan(fast_prev) or math.isnan(slow_prev))
        and fast_prev >= slow_prev
        and fast_now < slow_now
    )

    target = float(pos)

    if pos == 0.0:
        if bull_signal:
            atr = atr14[i]
            if not math.isnan(atr) and atr > 0:
                target = max(0.05, min(1.0, 0.01 * close[i] / atr))
        elif bear_signal:
            atr = atr14[i]
            if not math.isnan(atr) and atr > 0:
                target = -max(0.05, min(1.0, 0.01 * close[i] / atr))
    elif pos > 0:
        if bear_signal:
            target = 0.0
    else:
        if bull_signal:
            target = 0.0

    stop = None
    take = None

    entry_price = state.get("entry_price", math.nan)
    entry_atr = state.get("entry_atr", math.nan)
    best_price = state.get("best_price", math.nan)
    direction = state.get("direction", 0)

    if pos != 0.0 and not (math.isnan(entry_price) or math.isnan(entry_atr)) and entry_atr > 0:
        if direction == 0:
            direction = 1 if pos > 0 else -1

        if math.isnan(best_price):
            best_price = entry_price

        if pos > 0:
            best_price = max(best_price, high[i])
            if close[i] >= entry_price + 1.5 * entry_atr:
                stop = entry_price
            trail = best_price - 1.5 * entry_atr
            stop = trail if stop is None else max(stop, trail)
        else:
            best_price = min(best_price, low[i])
            if close[i] <= entry_price - 1.5 * entry_atr:
                stop = entry_price
            trail = best_price + 1.5 * entry_atr
            stop = trail if stop is None else min(stop, trail)

        if "signal_pos" not in state:
            state["signal_pos"] = float(pos)

    if pos == 0.0:
        state["entry_price"] = float(close[i])
        state["entry_atr"] = float(atr14[i]) if not math.isnan(atr14[i]) else math.nan
        state["best_price"] = float(close[i])
        state["direction"] = 0
    else:
        state["entry_price"] = float(entry_price) if not math.isnan(entry_price) else float(close[i])
        state["entry_atr"] = float(entry_atr) if not math.isnan(entry_atr) else float(atr14[i]) if not math.isnan(atr14[i]) else math.nan
        state["best_price"] = float(best_price)
        state["direction"] = direction

    if stop is not None and not math.isfinite(stop):
        stop = None

    return {"target": float(target), "stop": stop, "take": take}

