    n = len(hist) - 1

    # Indicator series
    atr14 = ind.atr(hist, 14)
    hh96 = ind.highest(high, 96)
    ll96 = ind.lowest(low, 96)

    c = float(close[-1])
    a = float(atr14[-1]) if not math.isnan(float(atr14[-1])) else float("nan")
    prior_hh = float(hh96[-2]) if n >= 1 else float("nan")
    prior_ll = float(ll96[-2]) if n >= 1 else float("nan")

    # Initialize persistent state keys safely
    if "sig" not in state:
        state["sig"] = 0  # 1 long, -1 short, 0 flat/none
    if "entry_bar" not in state:
        state["entry_bar"] = -1
    if "entry_px" not in state:
        state["entry_px"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "anchor" not in state:
        state["anchor"] = 0.0
    if "cool_until" not in state:
        state["cool_until"] = -1

    sig = int(state["sig"])
    entry_bar = int(state["entry_bar"])
    entry_px = float(state["entry_px"])
    entry_atr = float(state["entry_atr"])
    anchor = float(state["anchor"])
    cool_until = int(state["cool_until"])

    # Determine if a position is currently live from engine state
    in_trade = pos != 0.0

    # Exit if opposite Donchian signal while in trade
    long_sig = False
    short_sig = False
    if n >= 96 and not math.isnan(prior_hh) and not math.isnan(prior_ll):
        long_sig = c > prior_hh
        short_sig = c < prior_ll

    if in_trade:
        if sig > 0 and short_sig:
            # Opposite signal to long: flat next open
            state["sig"] = 0
            state["entry_bar"] = -1
            state["entry_px"] = 0.0
            state["entry_atr"] = 0.0
            state["anchor"] = 0.0
            state["cool_until"] = n + 4
            return {"target": 0.0, "stop": None, "take": None}
        if sig < 0 and long_sig:
            # Opposite signal to short: flat next open
            state["sig"] = 0
            state["entry_bar"] = -1
            state["entry_px"] = 0.0
            state["entry_atr"] = 0.0
            state["anchor"] = 0.0
            state["cool_until"] = n + 4
            return {"target": 0.0, "stop": None, "take": None}

        # Update moving anchor and derive stop/take from the box_shift logic
        if sig > 0:
            if anchor == 0.0:
                anchor = entry_px
            if not math.isnan(a) and entry_atr > 0.0:
                step = entry_atr
                if c >= anchor + step:
                    shifts = int(math.floor((c - anchor) / step))
                    if shifts > 0:
                        anchor += shifts * step
                        state["anchor"] = anchor
            stop = anchor - entry_atr
            take = anchor + 2.0 * entry_atr
            return {"target": pos, "stop": stop, "take": take}

        if sig < 0:
            if anchor == 0.0:
                anchor = entry_px
            if not math.isnan(a) and entry_atr > 0.0:
                step = entry_atr
                if c <= anchor - step:
                    shifts = int(math.floor((anchor - c) / step))
                    if shifts > 0:
                        anchor -= shifts * step
                        state["anchor"] = anchor
            stop = anchor + entry_atr
            take = anchor - 2.0 * entry_atr
            return {"target": pos, "stop": stop, "take": take}

    # Flat: handle cooldown and entry
    if n <= cool_until:
        return {"target": 0.0, "stop": None, "take": None}

    if n < 96 or math.isnan(prior_hh) or math.isnan(prior_ll) or math.isnan(a):
        return {"target": 0.0, "stop": None, "take": None}

    if long_sig:
        state["sig"] = 1
        state["entry_bar"] = n
        state["entry_px"] = c
        state["entry_atr"] = a
        state["anchor"] = c
        return {"target": 1.0, "stop": c - a, "take": c + 2.0 * a}

    if short_sig:
        state["sig"] = -1
        state["entry_bar"] = n
        state["entry_px"] = c
        state["entry_atr"] = a
        state["anchor"] = c
        return {"target": -1.0, "stop": c + a, "take": c - 2.0 * a}

    return {"target": 0.0, "stop": None, "take": None}

