    low = hist.low

    atr14 = ind.atr(hist, 14)
    cur_atr = float(atr14[-1]) if not math.isnan(float(atr14[-1])) else None

    box_n = 32
    box_w = 3.0
    time_n = 64
    fixed_size = 1.0

    tgt = pos
    stop = None
    take = None

    if pos == 0.0:
        hh = ind.highest(high[:-1], box_n)[-1] if len(high) > 1 else float("nan")
        ll = ind.lowest(low[:-1], box_n)[-1] if len(low) > 1 else float("nan")
        if cur_atr is not None and not math.isnan(hh) and not math.isnan(ll):
            box_height = hh - ll
            valid_box = box_height <= box_w * cur_atr
            if valid_box:
                c = float(close[-1])
                if c > hh:
                    tgt = fixed_size
                    state["sig_bar"] = n - 1
                    state["entry_atr"] = cur_atr
                    state["dir"] = 1
                elif c < ll:
                    tgt = -fixed_size
                    state["sig_bar"] = n - 1
                    state["entry_atr"] = cur_atr
                    state["dir"] = -1
    else:
        sig_bar = int(state.get("sig_bar", n - 1))
        bars_since = (n - 1) - sig_bar
        if bars_since >= time_n:
            tgt = 0.0
            if "sig_bar" in state:
                del state["sig_bar"]
            if "entry_atr" in state:
                del state["entry_atr"]
            if "dir" in state:
                del state["dir"]

    if pos != 0.0:
        sig_bar = int(state.get("sig_bar", n - 1))
        bars_since = (n - 1) - sig_bar
        entry_atr = float(state.get("entry_atr", cur_atr if cur_atr is not None else 0.0))
        direction = 1 if pos > 0 else -1
        entry_price = float(close[sig_bar]) if sig_bar < len(close) else float(close[-1])

        if direction > 0:
            stop = entry_price - entry_atr
            if bars_since >= time_n:
                tgt = 0.0
                stop = None
        else:
            stop = entry_price + entry_atr
            if bars_since >= time_n:
                tgt = 0.0
                stop = None

        if tgt == 0.0 and pos != 0.0:
