    bh = float(donch_high[-1])
    bl = float(donch_low[-1])

    atr14 = ind.atr(hist, 14)
    cur_atr = float(atr14[-1])
    if not np.isfinite(cur_atr) or cur_atr <= 0:
        return {"target": float(pos), "stop": None, "take": None}

    signal_long = c > bh
    signal_exit = c < bl

    target = float(pos)
    stop = None
    take = None

    # initialize / maintain trade state
    in_trade = abs(pos) > 1e-12

    if not in_trade:
        for k in ("entry_price", "entry_atr", "anchor", "signal_bar"):
            if k in state:
                del state[k]

    if in_trade:
        entry_price = float(state.get("entry_price", c))
        entry_atr = float(state.get("entry_atr", cur_atr))
        anchor = float(state.get("anchor", entry_price))
        signal_bar = int(state.get("signal_bar", n))

        # time stop: exit on bar where bars-since-signal reaches 64
        if n - signal_bar >= 64:
            target = 0.0
        elif signal_exit:
            target = 0.0
        else:
            # moving box
            if pos > 0:
                move = 0.0
                if entry_atr > 0:
                    move = math.floor((c - anchor) / entry_atr)
                if move > 0:
                    anchor += move * entry_atr
                stop = anchor - 2.0 * entry_atr
                take = anchor + 3.0 * entry_atr

                # breakeven once 1.5 ATR in profit
                if c >= entry_price + 1.5 * entry_atr:
                    stop = max(stop, entry_price)
            else:
                move = 0.0
                if entry_atr > 0:
                    move = math.floor((anchor - c) / entry_atr)
                if move > 0:
                    anchor -= move * entry_atr
                stop = anchor + 2.0 * entry_atr
                take = anchor - 3.0 * entry_atr

                if c <= entry_price - 1.5 * entry_atr:
                    stop = min(stop, entry_price)

            state["anchor"] = float(anchor)

    else:
        if signal_long:
            target = min(1.0, max(0.05, 0.0025 * c / (2.0 * cur_atr))))
            state["entry_price"] = float(c)
            state["entry_atr"] = float(cur_atr)
            state["anchor"] = float(c)
            state["signal_bar"] = int(n)

    return {"target": float(target), "stop": None if stop is None else float(stop), "take": None if take is None else float(take)}

