    htf_close = htf.close
    htf_ema20 = ind.ema(htf_close, 20)
    htf_ok = False
    if len(htf_close) > 0:
        hc = float(htf_close[-1])
        he = float(htf_ema20[-1]) if not np.isnan(htf_ema20[-1]) else float("nan")
        htf_ok = (not math.isnan(hc)) and (not math.isnan(he)) and (hc > he)

    # --- state init ---
    if "in_trade" not in state:
        state["in_trade"] = False
    if "entry_bar" not in state:
        state["entry_bar"] = -1
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "armed" not in state:
        state["armed"] = False
    if "box_top" not in state:
        state["box_top"] = 0.0
    if "box_bottom" not in state:
        state["box_bottom"] = 0.0
    if "cooldown_until" not in state:
        state["cooldown_until"] = -1

    # detect position status transitions
    if pos == 0.0 and state["in_trade"]:
        state["in_trade"] = False
        state["cooldown_until"] = t + 4

    if pos != 0.0:
        state["in_trade"] = True

    # --- signal calculation: 64-bar box breakout ---
    bullish = False
    if len(hist) >= 65 and not math.isnan(atr):
        top = float(np.max(high[-65:-1]))
        bot = float(np.min(low[-65:-1]))
        if (top - bot) <= 4.0 * atr and float(close[-1]) > top:
            bullish = True
            state["armed"] = True
            state["box_top"] = top
            state["box_bottom"] = bot

    # --- entry / exit target ---
    target = pos
    can_enter = (pos == 0.0) and (t >= state["cooldown_until"]) and htf_ok

    if pos != 0.0:
        # Flat on any short signal; this strategy only trades long, so no short entries.
        if bullish:
            target = pos
        else:
            target = pos
    else:
        if bullish and can_enter:
            if pos == 0.0:
                if not math.isnan(atr) and atr > 0.0:
                    frac = 0.01 * float(close[-1]) / (2.0 * atr)
                    frac = max(0.05, min(1.0, frac))
                    target = round(frac / 0.05) * 0.05
                else:
                    target = 0.0

    # --- manage trade state on entry ---
    if pos == 0.0 and target > 0.0:
        state["in_trade"] = True
        state["entry_bar"] = t
        state["entry_price"] = float(close[-1])
        state["entry_atr"] = atr

    # --- risk orders ---
    stop = None
    take = None

    if pos != 0.0 or target > 0.0:
        ep = state["entry_price"] if state["entry_price"] > 0 else float(close[-1])
        ea = state["entry_atr"] if state["entry_atr"] > 0 else atr

        if pos > 0.0:
            stop = ep - 1.0 * ea

            # time stop: exit after 64 bars since signal bar, decided on that bar
            if state["entry_bar"] >= 0 and (t - state["entry_bar"]) >= 64:
                target = 0.0

        if target > 0.0 and pos == 0.0:
            # entry bar; protective stop active next bar
            stop = ep - 1.0 * ea

    # if already in a trade, keep protective stop active
    if pos > 0.0:
        ep = state["entry_price"]
        ea = state["entry_atr"] if state["entry_atr"] > 0 else atr
        stop = ep - 1.0 * ea
        if state["entry_bar"] >= 0 and (t - state["entry_bar"]) >= 64:
            target = 0.0

    # restore cooldown tracking when trade ends
    if pos == 0.0 and target == 0.0 and state["in_trade"] is False:
        pass

    return {"target": float(target), "stop": stop, "take": take}

