            if pos > 0:
                if c >= last_add_price + entry_atr:
                    target = min(1.0, pos + 0.25)
                    if target != pos:
                        state["last_add_price"] = c
                        state["adds_used"] = adds_used + 1
            elif pos < 0:
                if c <= last_add_price - entry_atr:
                    target = max(-1.0, pos - 0.25)
