                        state["adds_used"] = adds_used + 1

    # --- Exit risk blocks ---
    stop = None
    take = None

    # Hard take-profit at 6 ATR from entry price
    if pos != 0.0 and "entry_atr" in state and not math.isnan(state.get("entry_atr", float("nan"))):
        entry_atr = float(state["entry_atr"])
