    rsi = ind.rsi(close, 14)

    if n < 2 or math.isnan(rsi[-1]) or math.isnan(rsi[-2]):
        return {"target": pos, "stop": None, "take": None}

    now = n - 1

    long_sig = (rsi[-2] < 25.0) and (rsi[-1] >= 25.0)
    short_sig = (rsi[-2] > 75.0) and (rsi[-1] <= 75.0)

    # Initialize persistent state
    if "entry_bar" not in state:
        state["entry_bar"] = -1
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "base_target" not in state:
        state["base_target"] = 0.0
    if "half_taken" not in state:
        state["half_taken"] = False
    if "cooldown_until" not in state:
        state["cooldown_until"] = -1
    if "last_pos" not in state:
        state["last_pos"] = 0.0

    # Detect trade lifecycle changes
    prev_pos = state["last_pos"]
    if prev_pos != 0.0 and pos == 0.0:
        state["cooldown_until"] = now + 16
        state["entry_bar"] = -1
        state["entry_price"] = 0.0
        state["entry_atr"] = 0.0
        state["base_target"] = 0.0
        state["half_taken"] = False

    if prev_pos == 0.0 and pos != 0.0:
        state["entry_bar"] = now
        state["entry_price"] = close[-1]
        atr = ind.atr(hist, 14)
        state["entry_atr"] = float(atr[-1]) if not math.isnan(atr[-1]) else 0.0
        state["base_target"] = abs(pos)
        state["half_taken"] = False

    state["last_pos"] = pos

    # Cooldown blocks new entries
    in_cooldown = now < state["cooldown_until"]

    target = pos
    stop = None
    take = None

    if pos != 0.0:
        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        if entry_atr <= 0.0:
            entry_atr = float(ind.atr(hist, 14)[-1])

        # Opposite signal while in trade: exit next open
        if (pos > 0 and short_sig) or (pos < 0 and long_sig):
            target = 0.0
            state["half_taken"] = False
            return {"target": target, "stop": None, "take": None}

        # Partial take once at +3 ATR close, halve position
        if (not state["half_taken"]) and entry_atr > 0.0:
            if pos > 0 and close[-1] >= entry_price + 3.0 * entry_atr:
                target = round((pos / 2.0) / 0.05) * 0.05
                state["half_taken"] = True
            elif pos < 0 and close[-1] <= entry_price - 3.0 * entry_atr:
                target = round((pos / 2.0) / 0.05) * 0.05
                state["half_taken"] = True

        # Protective take-profit and stop
        if entry_atr > 0.0:
            if pos > 0:
                stop = entry_price - 2.0 * entry_atr
                take = entry_price + 2.0 * entry_atr
            else:
                stop = entry_price + 2.0 * entry_atr
                take = entry_price - 2.0 * entry_atr

        # Time stop at 16 bars after signal bar
        if state["entry_bar"] >= 0 and (now - state["entry_bar"]) >= 16:
            target = 0.0
            return {"target": target, "stop": None, "take": None}

    else:
        # Flat: consider entries only if not in cooldown
        if not in_cooldown:
            if long_sig:
                target = 1.0
            elif short_sig:
                target = -1.0

    return {"target": target, "stop": stop, "take": take}

