        state["entry_atr"] = float(atr_now) if not math.isnan(float(atr_now)) else 0.0
        state["entry_bar"] = t
        state["half_done"] = False
        state["be_done"] = False
        state["entries_day"] = int(state["entries_day"]) + 1

    target = pos
    stop = None
    take = None

    if pos == 0.0:
        can_enter = int(state["entries_day"]) < 3 and (t - int(state["flat_since"])) >= 4
        valid_box = (not math.isnan(box_h)) and (not math.isnan(atr_now)) and box_h <= 4.0 * float(atr_now)
        long_sig = valid_box and close[-1] > box_top
        short_sig = valid_box and close[-1] < box_bot
        if can_enter:
            if long_sig:
                target = 1.0 if 1.0 <= 1.0 else 1.0
            elif short_sig:
                target = -1.0
    else:
        ep = float(state["entry_price"])
        ea = float(state["entry_atr"])
        if ea > 0.0 and not math.isnan(ea):
            if pos > 0:
                if close[-1] >= ep + 2.0 * ea:
                    state["be_done"] = True
                if close[-1] >= ep + 1.5 * ea and not state["half_done"]:
                    target = pos / 2.0
                    state["half_done"] = True
                if state["be_done"]:
                    stop = ep
                if close[-1] < box_bot:
                    target = 0.0
