                if close[-1] <= ep - 2.0 * ea:
                    state["be_done"] = True
                if close[-1] <= ep - 1.5 * ea and not state["half_done"]:
                    target = pos / 2.0
                    state["half_done"] = True
                if state["be_done"]:
                    stop = ep
                if close[-1] > box_top:
                    target = 0.0

    state["last_pos"] = float(pos if target == pos else target)
    return {"target": float(max(-1.0, min(1.0, target))), "stop": stop, "take": take}

