    cur_atr = float(atr[-1])

    target = pos
    stop = None
    take = None

    # Initialize persistent state
    if "day" not in state:
        state["day"] = -1
    if "entries_today" not in state:
        state["entries_today"] = 0
    if "cooldown_until" not in state:
        state["cooldown_until"] = -1
    if "had_pos" not in state:
        state["had_pos"] = False

    # Detect flat transition to start cooldown after trade ends
    if pos == 0.0:
        if state["had_pos"]:
            state["cooldown_until"] = i + 48
        state["had_pos"] = False
    else:
        state["had_pos"] = True

    # Daily counter based on UTC calendar day of signal bar open time
    day_key = int(hist.time[-1] // 86400000)
    if state["day"] != day_key:
        state["day"] = day_key
        state["entries_today"] = 0

    # Exit on opposite signal if in a position
    long_signal = False
    short_signal = False
    if len(hist) > 1 and not math.isnan(cur_rsi) and not math.isnan(prev_rsi):
        long_signal = prev_rsi < 30.0 and cur_rsi >= 30.0
        short_signal = prev_rsi > 70.0 and cur_rsi <= 70.0

    if pos > 0.0 and short_signal:
        target = 0.0
        return {"target": target, "stop": None, "take": None}

    if pos < 0.0 and long_signal:
        target = 0.0
        return {"target": target, "stop": None, "take": None}

    # No new entries while cooling down or over daily cap
    if pos == 0.0:
        if i < state["cooldown_until"]:
            return {"target": 0.0, "stop": None, "take": None}
        if state["entries_today"] >= 2:
            return {"target": 0.0, "stop": None, "take": None}

        # Entry logic
        if long_signal and not math.isnan(cur_atr) and cur_atr > 0.0:
            frac = 0.01 * cur_close / (2.0 * cur_atr)
            if frac < 0.05:
                frac = 0.05
            if frac > 1.0:
                frac = 1.0
            target = frac
            state["entries_today"] += 1
        elif short_signal and not math.isnan(cur_atr) and cur_atr > 0.0:
            frac = 0.01 * cur_close / (2.0 * cur_atr)
            if frac < 0.05:
                frac = 0.05
            if frac > 1.0:
                frac = 1.0
            target = -frac
            state["entries_today"] += 1
        else:
            target = 0.0

    return {"target": float(target), "stop": None, "take": None}

