        # New breakout arms setup, replacing any previous one
        if close[-1] > prior_high:
            state["armed_dir"] = 1
            state["armed_level"] = prior_high
            state["armed_until"] = t + 16
        elif close[-1] < prior_low:
            state["armed_dir"] = -1
            state["armed_level"] = prior_low
            state["armed_until"] = t + 16

    # Expire armed setup
    if state["armed_dir"] != 0 and t > state["armed_until"]:
