    # --- Entry/exit signal from armed retest ---
    entry_dir = 0
    if state["armed_dir"] == 1 and t <= state["armed_until"]:
        if low[-1] <= state["armed_level"]:
            entry_dir = 1
            state["armed_dir"] = 0
            state["armed_until"] = -1
    elif state["armed_dir"] == -1 and t <= state["armed_until"]:
        if high[-1] >= state["armed_level"]:
            entry_dir = -1
            state["armed_dir"] = 0
            state["armed_until"] = -1

    # --- Cooldown and entry permission ---
    can_enter = (t >= state["cooldown_until"])

    # Enter only when flat
    if pos == 0.0 and entry_dir != 0 and can_enter:
        out_target = 0.5 * entry_dir
        state["entry_atr"] = atr
        state["entry_price"] = float(close[-1])
        state["entry_bar"] = t
        state["last_add_price"] = float(close[-1])
        state["adds_used"] = 0

    # --- Pyramid management ---
    if pos != 0.0:
        entry_atr = float(state.get("entry_atr", atr))
        if entry_atr > 0:
            # Determine sign and current exposure scale
            sgn = 1 if pos > 0 else -1
            # Add only while in profit by at least 1 ATR from last add
            if state["adds_used"] < 2:
