                        out_target = -min(1.0, abs(pos) + 0.5)
                        state["last_add_price"] = float(close[-1])
                        state["adds_used"] += 1

    # --- Opposite signal flips us out at next open: close current position on opposite signal ---
    if pos != 0.0 and entry_dir != 0 and ((pos > 0 and entry_dir < 0) or (pos < 0 and entry_dir > 0)):
        out_target = 0.0

    # No additional stop/take beyond the explicit strategy instructions
    state["last_pos"] = pos
    return {"target": float(out_target), "stop": out_stop, "take": out_take}

