    state["was_in_pos"] = pos != 0.0

    # HTF trend filter: last completed 1h close above its 50 EMA
    htf60 = hist.htf(60)
    hclose = htf60.close
    hema = ind.ema(hclose, 50)
    trend_ok = False
    if len(hclose) > 0 and not np.isnan(hema[-1]):
        trend_ok = hclose[-1] > hema[-1]

    # Signal: 64-bar box breakout with height <= 6 ATR
    box_n = 64
    box_w = 6.0
    atr14 = ind.atr(hist, 14)
    if n <= box_n or np.isnan(atr14[-1]):
        return {"target": pos, "stop": None, "take": None}

    top = np.max(high[-box_n - 1:-1])
    bot = np.min(low[-box_n - 1:-1])
    height = top - bot
    long_signal = (close[-1] > top) and (height <= box_w * atr14[-1])

    # Long-only: if a short signal existed, flatten. Here signal is only long, so no-op.
    if pos == 0.0:
        if not trend_ok:
            return {"target": 0.0, "stop": None, "take": None}
        if not long_signal:
            return {"target": 0.0, "stop": None, "take": None}

        # Volatility-scaled sizing: 0.25% risk per 2 ATRs, capped [0.05, 1.0]
        frac = 0.0025 * close[-1] / (2.0 * atr14[-1])
        frac = max(0.05, min(1.0, frac))

        state["entry_bar"] = n - 1
        state["entry_atr"] = float(atr14[-1])
        state["entry_price"] = float(close[-1])
        state["stop_price"] = float(close[-1] - 1.5 * atr14[-1])

        return {"target": float(frac), "stop": float(state["stop_price"]), "take": None}

    # In position: maintain hard stop
    stop_price = state.get("stop_price", None)
    if stop_price is None:
        stop_price = float(close[-1] - 1.5 * atr14[-1])
        state["stop_price"] = stop_price

    return {"target": pos, "stop": float(stop_price), "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    close = hist.close
    high = hist.high
    low = hist.low

    t = len(hist) - 1
    c = float(close[-1])

    box_n = 64
    box_w = 4.0
    frac = 0.5
    shift_lo = 2.0
    shift_hi = 3.0
    shift_step = 1.0
    time_n = 128
    daily_k = 3

    if "day" not in state:
        state["day"] = -1
    if "entries_day" not in state:
        state["entries_day"] = 0
    if "cooldown_until" not in state:
        state["cooldown_until"] = -1
    if "in_trade" not in state:
        state["in_trade"] = False
    if "entry_bar" not in state:
        state["entry_bar"] = -1
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "anchor" not in state:
        state["anchor"] = 0.0
    if "shifted" not in state:
        state["shifted"] = 0
    if "dir" not in state:
        state["dir"] = 0
    if "pending" not in state:
        state["pending"] = 0

    atr14 = ind.atr(hist, 14)
    atr = float(atr14[-1])

    day = int(hist.time[-1] // 86400000)
    if day != state["day"]:
        state["day"] = day
        state["entries_day"] = 0

    if pos == 0.0:
        if state["in_trade"]:
            state["in_trade"] = False
            state["dir"] = 0
            state["shifted"] = 0
            state["anchor"] = 0.0
            state["entry_bar"] = -1
            state["entry_price"] = 0.0
            state["entry_atr"] = 0.0
            state["pending"] = 0
            state["cooldown_until"] = t + 4

    if state["in_trade"]:
        if t == state["entry_bar"]:
            state["anchor"] = state["entry_price"]
        if state["dir"] == 1:
            if c >= state["anchor"] + shift_step * state["entry_atr"]:
                nshift = int((c - state["anchor"]) // (shift_step * state["entry_atr"]))
                if nshift > 0:
                    state["anchor"] += nshift * shift_step * state["entry_atr"]
                    state["shifted"] += nshift
            stop = state["anchor"] - shift_lo * state["entry_atr"]
            take = state["anchor"] + shift_hi * state["entry_atr"]
        else:
            if c <= state["anchor"] - shift_step * state["entry_atr"]:
                nshift = int((state["anchor"] - c) // (shift_step * state["entry_atr"]))
                if nshift > 0:
                    state["anchor"] -= nshift * shift_step * state["entry_atr"]
                    state["shifted"] += nshift
            stop = state["anchor"] + shift_lo * state["entry_atr"]
            take = state["anchor"] - shift_hi * state["entry_atr"]

        if t - state["entry_bar"] >= time_n:
            state["pending"] = 0
            return {"target": 0.0, "stop": None, "take": None}

        return {"target": pos, "stop": stop, "take": take}

    if t < box_n:
        return {"target": pos, "stop": None, "take": None}

    if t <= state["cooldown_until"]:
        return {"target": pos, "stop": None, "take": None}

    if state["entries_day"] >= daily_k:
        return {"target": pos, "stop": None, "take": None}

    box_high = float(np.max(high[-box_n-1:-1]))
    box_low = float(np.min(low[-box_n-1:-1]))
    box_height = box_high - box_low

    long_sig = c > box_high and box_height <= box_w * atr
    short_sig = c < box_low and box_height <= box_w * atr

    if pos != 0.0:
        if (pos > 0 and short_sig) or (pos < 0 and long_sig):
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    if long_sig or short_sig:
        state["in_trade"] = True
        state["entry_bar"] = t
        state["entry_price"] = c
        state["entry_atr"] = atr
        state["anchor"] = c
        state["shifted"] = 0
        state["dir"] = 1 if long_sig else -1
        state["entries_day"] += 1
        if state["dir"] == 1:
            return {"target": frac, "stop": c - shift_lo * atr, "take": c + shift_hi * atr}
        return {"target": -frac, "stop": c + shift_lo * atr, "take": c - shift_hi * atr}

    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    close = hist.close
    rsi = ind.rsi(close, 21)
    atr = ind.atr(hist, 14)
    i = len(hist) - 1

    if "in_trade" not in state:
        state["in_trade"] = False
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_bar" not in state:
        state["entry_bar"] = -1
    if "partial_done" not in state:
        state["partial_done"] = False
    if "stop_level" not in state:
        state["stop_level"] = 0.0
    if "take_level" not in state:
        state["take_level"] = 0.0

    if pos == 0.0:
        state["in_trade"] = False

    target = pos
    stop = None
    take = None

    long_signal = False
    exit_signal = False

    if i >= 1 and not math.isnan(rsi[i - 1]) and not math.isnan(rsi[i]):
        long_signal = (rsi[i - 1] < 20.0 and rsi[i] >= 20.0)
        exit_signal = (rsi[i - 1] > 80.0 and rsi[i] <= 80.0)

    if pos == 0.0:
        state["in_trade"] = False
        state["partial_done"] = False
        if long_signal:
            target = 0.5
            state["in_trade"] = True
            state["entry_bar"] = i
            state["entry_price"] = float(close[-1])
            state["entry_atr"] = float(atr[-1]) if not math.isnan(atr[-1]) else 0.0
            state["stop_level"] = 0.0
            state["take_level"] = 0.0
    else:
        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        if entry_atr > 0.0:
            if not state["partial_done"] and close[-1] >= entry_price + 2.0 * entry_atr:
                target = 0.25
                state["partial_done"] = True
                state["stop_level"] = entry_price
            elif exit_signal:
                target = 0.0
            else:
                target = pos
            stop = state["stop_level"] if state["stop_level"] > 0.0 else None
            take = entry_price + 3.0 * entry_atr
        else:
            if exit_signal:
                target = 0.0
            else:
                target = pos

    return {"target": float(target), "stop": stop, "take": take}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    n = len(hist)
    close = hist.close
    high = hist.high
    low = hist.low
    time = hist.time

    # Warm-up safety
    if n < 193:
        return {"target": pos, "stop": None, "take": None}

    # Daily cap: at most 2 new entries per UTC calendar day, counted by signal bar open time
    day = int(time[-1] // 86400000)
    last_day = state.get("day", -1)
    if day != last_day:
        state["day"] = day
        state["entries_today"] = 0
    entries_today = int(state.get("entries_today", 0))

    # Detect current setup
    prior_high = np.max(high[-193:-1])
    bullish = close[-1] > prior_high

    # Long-only system: bearish signal means flatten if currently long
    if pos > 0:
        if not bullish:
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    # Flat: only enter on bullish breakout, subject to daily cap
    if pos == 0 and bullish and entries_today < 2:
        state["entries_today"] = entries_today + 1
        return {"target": 1.0, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}
